  brush.fill("#ff4500", 100);  // Sun
  brush.fillTexture(0.8, 0);  // Add some texture to the sun

  // Paint the sun as a circle
  brush.beginShape();
  brush.vertex(200, 200);  // Top of the sun
  brush.vertex(225, 180);  // Right top of the sun
  brush.vertex(200, 220);  // Bottom of the sun
  brush.vertex(175, 180);  // Left top of the sun
  brush.endShape(true);

  // Paint the hills again (the ground)
  brush.beginShape();
  brush.vertex(0, 0);  // Top left hill
  brush.vertex(400, 0);  // Top right hill
  brush.vertex(200, 100);  // Hill in the center
  brush.endShape(true);
}
